BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,name VARCHAR(255),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS climate_workspaces(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS climate_workspace_members(workspace_id UUID REFERENCES climate_workspaces(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','data_steward','model_steward','reviewer','analyst')),active BOOLEAN DEFAULT true,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS climate_idempotency(actor_id INTEGER,key TEXT,response JSONB NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS climate_dataset_versions(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES climate_workspaces(id),name TEXT NOT NULL,version TEXT NOT NULL,source_uri TEXT NOT NULL,checksum TEXT NOT NULL,license TEXT NOT NULL,data_start DATE NOT NULL,data_end DATE NOT NULL,spatial_coverage JSONB NOT NULL,missing_ratio NUMERIC NOT NULL CHECK(missing_ratio BETWEEN 0 AND 1),status TEXT NOT NULL CHECK(status IN('registered','validated','rejected','superseded')),idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(workspace_id,name,version),UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS climate_model_versions(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES climate_workspaces(id),name TEXT NOT NULL,version TEXT NOT NULL,artifact_uri TEXT NOT NULL,checksum TEXT NOT NULL,training_manifest JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN('registered','validated','retired')),created_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(workspace_id,name,version));
CREATE TABLE IF NOT EXISTS climate_forecast_runs(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES climate_workspaces(id),dataset_version_id BIGINT REFERENCES climate_dataset_versions(id),model_version_id BIGINT REFERENCES climate_model_versions(id),region TEXT NOT NULL,horizon_start TIMESTAMPTZ NOT NULL,horizon_end TIMESTAMPTZ NOT NULL,parameters JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('queued','running','succeeded','failed','cancelled')),output_manifest JSONB,failure_code TEXT,idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS climate_forecast_values(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES climate_workspaces(id),run_id BIGINT REFERENCES climate_forecast_runs(id),valid_time TIMESTAMPTZ NOT NULL,variable TEXT NOT NULL,unit TEXT NOT NULL,point_value DOUBLE PRECISION NOT NULL,lower_value DOUBLE PRECISION NOT NULL,upper_value DOUBLE PRECISION NOT NULL,narrative TEXT,state TEXT NOT NULL CHECK(state IN('draft','published_research','withdrawn')),created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,published_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS climate_evaluations(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES climate_workspaces(id),model_version_id BIGINT REFERENCES climate_model_versions(id),dataset_version_id BIGINT REFERENCES climate_dataset_versions(id),region TEXT NOT NULL,horizon TEXT NOT NULL,metrics JSONB NOT NULL,subgroup JSONB NOT NULL,state TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS climate_audit_events(id BIGSERIAL PRIMARY KEY,workspace_id UUID REFERENCES climate_workspaces(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS climate_runs_workspace_state_idx ON climate_forecast_runs(workspace_id,state);
COMMIT;
